import urllib.request, concurrent.futures, re
urls=[
'https://ee.zju.edu.cn/32469/list.htm',
'https://yjszs.njnu.edu.cn/info/1073/16292.htm',
'https://gsas.seu.edu.cn/ssmlcx2026/pages/index.html',
'https://gs.hhu.edu.cn/2025/0930/c17279a308103/page.htm',
'https://gra.njtech.edu.cn/system/_content/download.jsp?owner=1816331650&urltype=news.DownloadAttachUrl&wbfileid=5423722',
'https://gs.njust.edu.cn/?_=_'
]
def fetch(u):
 try:
  r=urllib.request.urlopen(urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'}),timeout=20); b=r.read(); s=b.decode('utf-8','replace')
  if b[:4]==b'%PDF': return u,'PDF response, '+str(len(b))+' bytes'
  if 'hhu' in u: matches=re.findall(r'.{0,60}(?:\\.pdf|\\.zip|iframe|\\.docx).{0,100}',s)
  elif 'gsas' in u: matches=re.findall(r'<script["'^>]+src=[''^>]+>'"',s)
  elif 'njust' in u: matches=[x for x in re.findall(r'<a\\b["'^>]*>.*?</a>'"',s,re.S) if '2026年南京理工大学硕士' in x]
  else: matches=[x for x in re.findall(r'<a\\b["'^>]*>.*?</a>'"',s,re.S) if any(k in x for k in ['2026','2025','推免','目录','电气'])]
  return u, '\\n'.join(matches)[:12000]
 except Exception as e:return u,str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as e:
 for u,s in e.map(fetch,urls):print(u+'\\n'+s+'\\n')
PY"

